const fs = require('node:fs')
const assert = require('node:assert/strict')
const crm = fs.readFileSync('app/crm/comercial/page.tsx', 'utf8')
const kanban = fs.readFileSync('lib/kanban.ts', 'utf8')
assert.match(crm, /s==='aprovado'\|\|s==='convertido'\|\|s==='vendido'\?'ganho'/, 'Vendido deve aparecer como ganho no CRM')
assert.match(crm, /o\.status==='vendido'&&<span[^>]*>Venda confirmada<\/span>/, 'Card vendido deve identificar venda confirmada')
assert.match(kanban, /window\.location\.assign\(\`\/vendas\/confirmar/, 'Kanban deve abrir confirmação, sem confirmar automaticamente')
assert.match(crm, /\.from\('orcamentos'\)/, 'CRM deve utilizar os orçamentos existentes')
assert.doesNotMatch(crm, /\.insert\(|\.update\(|\.delete\(|\.upsert\(/, 'Visão CRM não deve gravar status de venda')
console.log('PASS: venda confirmada aparece como oportunidade ganha; confirmação Kanban intacta.')
